1	// Package batchreg registers supply-chain batches in a local JSON file.
2	//
3	// The registry file format is public and stable:
4	//
5	//	{
6	//	  "version": 1,
7	//	  "batches": [
8	//	    {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
9	//	  ]
10	//	}
11	//
12	// Batch ids are unique per file (compared byte for byte, so casing and
13	// interior characters matter). Re-registering an existing id with the same
14	// product, quantity and unit is an idempotent duplicate confirmation; any
15	// differing field is rejected without touching stored records.
16	package batchreg
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"io"
24		"io/fs"
25		"os"
26		"path/filepath"
27		"regexp"
28		"strconv"
29		"strings"
30		"unicode/utf8"
31	)
32	
33	// FormatVersion is the only registry file format understood by this build.
34	const FormatVersion = 1
35	
36	// MaxQuantity is the inclusive upper bound for a batch quantity.
37	const MaxQuantity = int64(1<<63 - 1)
38	
39	var quantityPattern = regexp.MustCompile(`^[0-9]+$`)
40	
41	// Batch is the four-piece record of one supply-chain batch.
42	type Batch struct {
43		Batch    string `json:"batch"`
44		Product  string `json:"product"`
45		Quantity int64  `json:"quantity"`
46		Unit     string `json:"unit"`
47	}
48	
49	// Registry is the on-disk registry file.
50	type Registry struct {
51		Version int     `json:"version"`
52		Batches []Batch `json:"batches"`
53	}
54	
55	// Input is a normalized registration request.
56	type Input struct {
57		Batch    string
58		Product  string
59		Quantity int64
60		Unit     string
61	}
62	
63	// Outcome reports what Register did.
64	type Outcome struct {
65		Batch   Batch
66		Created bool // true when a record was added, false for an identical repeat
67	}
68	
69	// ConflictError reports that a batch id is already held by a different record.
70	// Fields lists every differing member among "product", "quantity" and "unit".
71	type ConflictError struct {
72		Batch  string
73		Fields []string
74	}
75	
76	func (e *ConflictError) Error() string {
77		return fmt.Sprintf("batch %q is already registered with conflicting field(s): %s; the existing record cannot be overwritten",
78			e.Batch, strings.Join(e.Fields, ", "))
79	}
80	
81	// DuplicateIDError reports two stored records sharing one batch id.
82	// First and Second are the 1-based positions of the two records in the
83	// batches array when known.
84	type DuplicateIDError struct {
85		Batch  string
86		First  int
87		Second int
88	}
89	
90	func (e *DuplicateIDError) Error() string {
91		if e.First > 0 && e.Second > 0 {
92			return fmt.Sprintf("registry contains multiple records for batch %q (records %d and %d)", e.Batch, e.First, e.Second)
93		}
94		return fmt.Sprintf("registry contains multiple records for batch %q", e.Batch)
95	}
96	
97	// FormatError reports a structural violation of the public registry file
98	// format: a missing, duplicated, misspelled, null or mistyped field, or a
99	// field NAME whose bytes are not valid UTF-8 (or hold a lone surrogate
100	// escape) — either in the root object (Position == 0) or in one batch
101	// record (Position is its 1-based index in "batches"). Batch carries the
102	// record's batch id only when it is uniquely determined; it stays empty when
103	// the "batch" member itself is missing, duplicated or not a string. A bad
104	// field name is reported with an empty Field: the undecodable name is never
105	// quoted back, since decoding it would substitute U+FFFD.
106	type FormatError struct {
107		Position int
108		Batch    string
109		Field    string
110		Reason   string
111	}
112	
113	func (e *FormatError) Error() string {
114		where := "root object"
115		if e.Position > 0 {
116			where = fmt.Sprintf("batches record %d", e.Position)
117			if e.Batch != "" {
118				where += fmt.Sprintf(" (batch %q)", e.Batch)
119			}
120		}
121		if e.Field != "" {
122			return fmt.Sprintf("%s: field %q: %s", where, e.Field, e.Reason)
123		}
124		return fmt.Sprintf("%s: %s", where, e.Reason)
125	}
126	
127	// EncodingError reports that a text field is not valid UTF-8: either the
128	// bytes of a CLI argument, or a JSON string value whose source bytes hold
129	// malformed UTF-8 or a lone surrogate escape. The offending value is never
130	// quoted back, since decoding it would substitute U+FFFD and make distinct
131	// inputs collide. Field is one of "batch", "product" and "unit". Inside a
132	// manifest, ParseManifest wraps this in a ManifestRecordError carrying the
133	// 1-based record position.
134	type EncodingError struct {
135		Field string
136	}
137	
138	func (e *EncodingError) Error() string {
139		return fmt.Sprintf("field %q contains bytes that are not valid UTF-8; the value is rejected instead of being replaced with U+FFFD", e.Field)
140	}
141	
142	// NormalizeField trims leading and trailing whitespace; the result must stay
143	// non-empty and be valid UTF-8. Interior characters, including interior
144	// whitespace, are kept, and casing is preserved so "B1" and "b1" are
145	// different values. A genuine replacement character (U+FFFD) is ordinary
146	// text; only malformed UTF-8 bytes are refused.
147	func NormalizeField(value string) (string, error) {
148		if !utf8.ValidString(value) {
149			return "", errors.New("value is not valid UTF-8 text")
150		}
151		trimmed := strings.TrimSpace(value)
152		if trimmed == "" {
153			return "", errors.New("value must not be empty after trimming whitespace")
154		}
155		return trimmed, nil
156	}
157	
158	// ParseQuantity accepts a decimal positive integer made only of ASCII digits
159	// 0-9. Leading zeros are allowed; the numeric value is what gets stored and
160	// compared. Zero, signs, fractions, non-ASCII digits and values above the
161	// signed 64-bit maximum are rejected.
162	func ParseQuantity(text string) (int64, error) {
163		if !quantityPattern.MatchString(text) {
164			return 0, fmt.Errorf("quantity %q must be a positive decimal integer made only of digits 0-9", text)
165		}
166		value, err := strconv.ParseInt(text, 10, 64)
167		if err != nil {
168			return 0, fmt.Errorf("quantity %q must be a positive integer no greater than %d", text, MaxQuantity)
169		}
170		if value == 0 {
171			return 0, fmt.Errorf("quantity %q must be greater than zero", text)
172		}
173		return value, nil
174	}
175	
176	var (
177		errStringNotJSON  = errors.New("value is not a JSON string")
178		errStringEncoding = errors.New("JSON string contains bytes that are not valid UTF-8")
179	)
180	
181	// unmarshalStringStrict decodes one JSON string literal into a Go string
182	// without encoding/json's silent U+FFFD substitution. The literal must be
183	// syntactically valid JSON (only the single token, no trailing data) and the
184	// decoded text must be valid Unicode: malformed UTF-8 source bytes and lone
185	// surrogate escapes are refused, while a genuine U+FFFD — written directly
186	// or as the escape "�" — is ordinary text. Syntax problems return
187	// errStringNotJSON; encoding problems return errStringEncoding.
188	func unmarshalStringStrict(raw json.RawMessage) (string, error) {
189		token := trimJSONSpace(raw)
190		if len(token) < 2 || token[0] != '"' || token[len(token)-1] != '"' {
191			return "", errStringNotJSON
192		}
193		var b strings.Builder
194		b.Grow(len(token))
195		i := 1
196		for i < len(token)-1 {
197			c := token[i]
198			switch {
199			case c == '"':
200				// An unescaped quote before the final byte ends the literal
201				// early, so anything following it is trailing data.
202				return "", errStringNotJSON
203			case c == '\\':
204				if i+1 >= len(token)-1 {
205					return "", errStringNotJSON
206				}
207				switch token[i+1] {
208				case '"', '\\', '/':
209					b.WriteByte(token[i+1])
210					i += 2
211				case 'b':
212					b.WriteByte('\b')
213					i += 2
214				case 'f':
215					b.WriteByte('\f')
216					i += 2
217				case 'n':
218					b.WriteByte('\n')
219					i += 2
220				case 'r':
221					b.WriteByte('\r')
222					i += 2
223				case 't':
224					b.WriteByte('\t')
225					i += 2
226				case 'u':
227					r, size, err := decodeUnicodeEscape(token[i:])
228					if err != nil {
229						return "", err
230					}
231					if _, err := b.WriteRune(r); err != nil {
232						return "", errStringEncoding
233					}
234					i += size
235				default:
236					return "", errStringNotJSON
237				}
238			case c < 0x20:
239				// Raw control characters must be escaped in JSON.
240				return "", errStringNotJSON
241			default:
242				r, size := utf8.DecodeRune(token[i : len(token)-1])
243				if r == utf8.RuneError && size == 1 {
244					return "", errStringEncoding
245				}
246				b.WriteRune(r)
247				i += size
248			}
249		}
250		if i != len(token)-1 {
251			return "", errStringNotJSON
252		}
253		return b.String(), nil
254	}
255	
256	// decodeUnicodeEscape reads a "\uXXXX" escape (or a UTF-16 surrogate pair
257	// "\uHHHH\uLLLL") at the start of p, returning the rune and the number of
258	// bytes consumed. A high surrogate not followed by a low surrogate, a low
259	// surrogate with no high one, or a non-hex code unit are encoding errors.
260	func decodeUnicodeEscape(p []byte) (rune, int, error) {
261		hi, ok := hex4(p)
262		if !ok {
263			return 0, 0, errStringNotJSON
264		}
265		switch {
266		case hi >= 0xD800 && hi <= 0xDBFF:
267			if len(p) < 12 || p[6] != '\\' || p[7] != 'u' {
268				return 0, 0, errStringEncoding
269			}
270			lo, ok := hex4(p[6:])
271			if !ok {
272				return 0, 0, errStringNotJSON
273			}
274			if lo < 0xDC00 || lo > 0xDFFF {
275				return 0, 0, errStringEncoding
276			}
277			return 0x10000 + (rune(hi)-0xD800)<<10 + (rune(lo) - 0xDC00), 12, nil
278		case hi >= 0xDC00 && hi <= 0xDFFF:
279			return 0, 0, errStringEncoding
280		default:
281			return rune(hi), 6, nil
282		}
283	}
284	
285	// hex4 reads the four hex digits following a leading "\u" (p[:2] == `\u`).
286	func hex4(p []byte) (int, bool) {
287		if len(p) < 6 || p[0] != '\\' || p[1] != 'u' {
288			return 0, false
289		}
290		v := 0
291		for _, c := range p[2:6] {
292			var d byte
293			switch {
294			case c >= '0' && c <= '9':
295				d = c - '0'
296			case c >= 'a' && c <= 'f':
297				d = c - 'a' + 10
298			case c >= 'A' && c <= 'F':
299				d = c - 'A' + 10
300			default:
301				return 0, false
302			}
303			v = v<<4 | int(d)
304		}
305		return v, true
306	}
307	
308	// Load reads the registry at path. A missing file yields an empty registry
309	// with existed == false. An existing file that is empty, not parseable as
310	// the public format — including missing, null, duplicated, misspelled or
311	// mistyped fields — of an unsupported version, or holding duplicate batch
312	// ids is an error: callers must never overwrite such a file as if it were a
313	// fresh registry.
314	//
315	// A symbolic link is followed to its target, so reading through a link sees
316	// exactly the records Save writes to the linked file. A link whose target
317	// does not exist, or a chain of links forming a loop, is an error naming
318	// path and the reason — never a fresh-registry signal: treating it as a
319	// first registration would either replace the link with a regular file or
320	// create the target the user never asked for.
321	func Load(path string) (reg *Registry, existed bool, err error) {
322		data, err := os.ReadFile(path)
323		if err != nil {
324			if errors.Is(err, fs.ErrNotExist) {
325				// A dangling symbolic link also reports "not exist", but the path
326				// is occupied: the caller must not treat it as a first
327				// registration.
328				if info, lerr := os.Lstat(path); lerr == nil && info.Mode()&os.ModeSymlink != 0 {
329					return nil, true, fmt.Errorf("cannot read registry %q: symbolic link target does not exist; refusing to treat the link as a new registry", path)
330				}
331				return &Registry{Version: FormatVersion}, false, nil
332			}
333			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
334		}
335		if len(bytes.TrimSpace(data)) == 0 {
336			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
337		}
338		reg, err = decode(data)
339		if err != nil {
340			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
341		}
342		if err := validate(reg); err != nil {
343			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
344		}
345		return reg, true, nil
346	}
347	
348	// decode parses data as the public registry format. The root must be a JSON
349	// object holding exactly "version" (the integer 1) and "batches" (an array,
350	// possibly empty); every record must be an object holding exactly "batch",
351	// "product", "quantity" and "unit". Field names are matched case-sensitively
352	// after JSON string decoding, so "Version" or "Batch" are unknown fields and
353	// an escaped respelling such as "bat\u0063h" counts as the same field. A
354	// field NAME whose source bytes are malformed UTF-8, or that hides a lone
355	// surrogate escape, is its own rejection cause — reported as an invalid
356	// field name, never as "must be an object" and never as an unknown field
357	// under the U+FFFD-substituted text. A field appearing twice in one object
358	// is rejected even when both values are
359	// identical; missing fields, nulls, wrong types and unknown fields are
360	// rejected just the same. Nothing is patched up by taking the later value,
361	// merging or defaulting.
362	func decode(data []byte) (*Registry, error) {
363		dec := json.NewDecoder(bytes.NewReader(data))
364		var root json.RawMessage
365		if err := dec.Decode(&root); err != nil {
366			return nil, err
367		}
368		var extra json.RawMessage
369		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
370			if err == nil {
371				return nil, errors.New("unexpected data after registry object")
372			}
373			return nil, err
374		}
375	
376		fields, badKey, err := parseObjectFields(root)
377		if err != nil {
378			return nil, &FormatError{Reason: "root must be a JSON object holding exactly \"version\" and \"batches\""}
379		}
380		if badKey {
381			return nil, &FormatError{Reason: keyEncodingReason}
382		}
383		if dup, ok := duplicateField(fields); ok {
384			return nil, &FormatError{Field: dup, Reason: "field appears more than once; duplicate fields are not allowed"}
385		}
386		for _, f := range fields {
387			if f.key != "version" && f.key != "batches" {
388				return nil, &FormatError{Field: f.key, Reason: "unknown field; only \"version\" and \"batches\" are allowed"}
389			}
390		}
391		versionRaw, ok := findField(fields, "version")
392		if !ok {
393			return nil, &FormatError{Field: "version", Reason: "required field is missing"}
394		}
395		batchesRaw, ok := findField(fields, "batches")
396		if !ok {
397			return nil, &FormatError{Field: "batches", Reason: "required field is missing"}
398		}
399		version, err := parseRegistryVersion(versionRaw)
400		if err != nil {
401			return nil, err
402		}
403		if trimmed := bytes.TrimSpace(batchesRaw); len(trimmed) == 0 || trimmed[0] != '[' {
404			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
405		}
406		var elems []json.RawMessage
407		if err := json.Unmarshal(batchesRaw, &elems); err != nil {
408			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
409		}
410		reg := &Registry{Version: version, Batches: make([]Batch, 0, len(elems))}
411		for i, raw := range elems {
412			b, err := parseRegistryRecord(raw, i+1)
413			if err != nil {
414				return nil, err
415			}
416			reg.Batches = append(reg.Batches, b)
417		}
418		return reg, nil
419	}
420	
421	// parseRegistryVersion accepts exactly the integer literal of FormatVersion.
422	// Other integers report an unsupported version; anything else (strings,
423	// fractions, exponents, booleans, null, arrays, objects) is a type error.
424	func parseRegistryVersion(raw json.RawMessage) (int, error) {
425		token := string(bytes.TrimSpace(raw))
426		if isJSONInteger(token) {
427			if token == strconv.Itoa(FormatVersion) {
428				return FormatVersion, nil
429			}
430			return 0, fmt.Errorf("unsupported registry version: got %s, want %d", token, FormatVersion)
431		}
432		return 0, &FormatError{Field: "version", Reason: fmt.Sprintf("must be the integer %d, not %s", FormatVersion, token)}
433	}
434	
435	// parseRegistryRecord validates one batches element: a JSON object with
436	// exactly the four required lowercase fields, text fields as JSON strings
437	// and quantity as a strict JSON integer in 1..MaxQuantity. pos is the
438	// record's 1-based position in the batches array.
439	//
440	// The structural rules (member names, strict string decoding, quantity
441	// range) are shared with parseManifestRecord; only this source's reporting
442	// differs: problems are surfaced as *FormatError with registry wording, a
443	// duplicated member anywhere in the object outranks an unknown one, and
444	// text values are read verbatim — validate handles the empty-string case.
445	// A member name that cannot be decoded is reported as an invalid field name
446	// (keyEncodingReason), ahead of the duplicate/unknown scan, with the batch
447	// id attached under the same unambiguity rule as every other record error.
448	func parseRegistryRecord(raw json.RawMessage, pos int) (Batch, error) {
449		var b Batch
450		fields, badKey, err := parseObjectFields(raw)
451		if err != nil {
452			return b, &FormatError{Position: pos, Reason: "record must be a JSON object holding exactly \"batch\", \"product\", \"quantity\" and \"unit\""}
453		}
454		// The batch id is attached to errors only when it is unambiguous:
455		// exactly one "batch" member carrying a JSON string whose decoded text
456		// is valid UTF-8. When the "batch" member itself is duplicated, or its
457		// bytes are not valid UTF-8, no id (and never a U+FFFD replacement) is
458		// picked arbitrarily.
459		batchID := unambiguousBatchID(fields, textVerbatim)
460		if badKey {
461			return Batch{}, &FormatError{Position: pos, Batch: batchID, Reason: keyEncodingReason}
462		}
463		fail := func(field, reason string) (Batch, error) {
464			return Batch{}, &FormatError{Position: pos, Batch: batchID, Field: field, Reason: reason}
465		}
466	
467		switch fault := checkRecordMembers(fields, true); fault.kind {
468		case faultDuplicate:
469			return fail(fault.field, "field appears more than once; duplicate fields are not allowed")
470		case faultUnknown:
471			return fail(fault.field, "unknown field; only \"batch\", \"product\", \"quantity\" and \"unit\" are allowed")
472		}
473	
474		text := func(name string) (string, error) {
475			rawValue, ok := findField(fields, name)
476			value, problem, _ := decodeRecordText(rawValue, ok, textVerbatim)
477			switch problem {
478			case fieldMissing:
479				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "required field is missing"}
480			case fieldEncoding:
481				return "", &FormatError{Position: pos, Batch: batchID, Field: name,
482					Reason: "must be valid UTF-8 text: malformed bytes or lone surrogate escapes are rejected instead of being replaced with U+FFFD"}
483			case fieldNotString:
484				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
485			}
486			return value, nil
487		}
488		if b.Batch, err = text("batch"); err != nil {
489			return Batch{}, err
490		}
491		if b.Product, err = text("product"); err != nil {
492			return Batch{}, err
493		}
494		if b.Unit, err = text("unit"); err != nil {
495			return Batch{}, err
496		}
497		quantityRaw, ok := findField(fields, "quantity")
498		if !ok {
499			return fail("quantity", "required field is missing")
500		}
501		b.Quantity, err = registryQuantityError(bytes.TrimSpace(quantityRaw))
502		if err != nil {
503			return fail("quantity", err.Error())
504		}
505		return b, nil
506	}
507	
508	// isJSONInteger reports whether token is a JSON number literal without
509	// fraction or exponent. The token comes from validated JSON, so leading
510	// zeros cannot hide extra digits.
511	func isJSONInteger(token string) bool {
512		if token == "" {
513			return false
514		}
515		if token[0] == '-' {
516			token = token[1:]
517		}
518		if token == "" {
519			return false
520		}
521		for i := 0; i < len(token); i++ {
522			if token[i] < '0' || token[i] > '9' {
523				return false
524			}
525		}
526		return true
527	}
528	
529	// objectField is one member of a JSON object in source order; the key is
530	// the decoded JSON string, so escaped spellings compare by meaning.
531	type objectField struct {
532		key   string
533		value json.RawMessage
534	}
535	
536	// parseObjectFields decodes a single JSON object value into its members in
537	// source order, keeping duplicates visible for the caller to reject. Keys
538	// are re-scanned strictly: encoding/json would otherwise hand back U+FFFD
539	// substitutions for malformed key bytes.
540	//
541	// A member whose name cannot be decoded — malformed UTF-8 bytes or a lone
542	// surrogate escape — is reported through the badKey flag and dropped from
543	// the returned list: the substituted text encoding/json produced must never
544	// be treated as a real name, where it could collide with a genuine field or
545	// be misreported as an unknown field. Scanning still continues past such a
546	// member (its value is consumed normally) so every other member, a valid
547	// "batch" among them, stays visible to the caller's batch-id rule. The
548	// returned error is reserved for structural problems: the value not being an
549	// object, or malformed JSON inside it.
550	func parseObjectFields(raw []byte) (fields []objectField, badKey bool, err error) {
551		trimmed := bytes.TrimSpace(raw)
552		if len(trimmed) == 0 || trimmed[0] != '{' {
553			return nil, false, errors.New("value is not a JSON object")
554		}
555		dec := json.NewDecoder(bytes.NewReader(trimmed))
556		if _, err := dec.Token(); err != nil { // opening brace
557			return nil, false, err
558		}
559		for dec.More() {
560			keyStart := dec.InputOffset()
561			tok, err := dec.Token()
562			keyEnd := dec.InputOffset()
563			if err != nil {
564				return nil, false, err
565			}
566			key, ok := tok.(string)
567			if !ok {
568				return nil, false, errors.New("object keys must be JSON strings")
569			}
570			_, keyErr := unmarshalStringStrict(keyTokenBytes(trimmed, int(keyStart), int(keyEnd)))
571			var value json.RawMessage
572			if err := dec.Decode(&value); err != nil {
573				return nil, false, err
574			}
575			if keyErr != nil {
576				if errors.Is(keyErr, errStringEncoding) {
577					badKey = true
578					continue
579				}
580				return nil, false, keyErr
581			}
582			fields = append(fields, objectField{key: key, value: value})
583		}
584		if _, err := dec.Token(); err != nil { // closing brace
585			return nil, false, err
586		}
587		return fields, badKey, nil
588	}
