552			{"escaped unknown field name", `{"batch":"B-002","product":"P","quantity":1,"unit":"kg","supplie\u0072":"S"}`, 1, "B-002", "supplier"},
553			{"escaped batch spelling", `{"bat\u0063h":"B-002","product":"P","quantity":1,"unit":"kg","extra":1}`, 1, "B-002", "extra"},
554			{"unicode batch", `{"batch":"批次-🚚","product":"P","quantity":1,"unit":"kg","extra":1}`, 1, "批次-🚚", "extra"},
555			{"genuine replacement char batch", `{"batch":"�","product":"P","quantity":1,"unit":"kg","extra":1}`, 1, "�", "extra"},
556		}
557		for _, tc := range cases {
558			t.Run(tc.name, func(t *testing.T) {
559				content := `[{"batch":"B-001","product":"P","quantity":1,"unit":"kg"},` + tc.record + `]`
560				_, err := ParseManifest([]byte(content))
561				var re *ManifestRecordError
562				if !errors.As(err, &re) {
563					t.Fatalf("expected ManifestRecordError, got %v", err)
564				}
565				if re.Position != tc.wantPos+1 {
566					t.Fatalf("position=%d, want %d", re.Position, tc.wantPos+1)
567				}
568				if re.Batch != tc.wantBatch {
569					t.Fatalf("batch=%q, want %q (error: %v)", re.Batch, tc.wantBatch, err)
570				}
571				if !strings.Contains(re.Reason, strconv.Quote(tc.wantField)) {
572					t.Fatalf("reason %q must name field %q", re.Reason, tc.wantField)
573				}
574				if !strings.Contains(err.Error(), strconv.Quote(tc.wantBatch)) {
575					t.Fatalf("error text must name the batch id: %v", err)
576				}
577			})
578		}
579	}
580	
581	// The batch id stays out of the error when it cannot be determined uniquely
582	// and reliably: missing, mistyped, blank, malformed or duplicated "batch"
583	// members — duplicates even with identical values or an escaped respelling.
584	func TestParseManifestRecordErrorOmitsAmbiguousBatch(t *testing.T) {
585		cases := map[string]string{
586			"missing batch":             `[{"product":"P","quantity":1,"unit":"kg","supplier":"S"}]`,
587			"numeric batch":             `[{"batch":7,"product":"P","quantity":1,"unit":"kg","supplier":"S"}]`,
588			"null batch":                `[{"batch":null,"product":"P","quantity":1,"unit":"kg","supplier":"S"}]`,
589			"blank batch":               `[{"batch":"  ","product":"P","quantity":1,"unit":"kg","supplier":"S"}]`,
590			"duplicate batch distinct":  `[{"batch":"B-002","batch":"B-003","product":"P","quantity":1,"unit":"kg"}]`,
591			"duplicate batch identical": `[{"batch":"B-002","batch":"B-002","product":"P","quantity":1,"unit":"kg"}]`,
592			"duplicate batch escaped":   `[{"batch":"B-002","bat\u0063h":"B-002","product":"P","quantity":1,"unit":"kg"}]`,
593			"lone surrogate batch":      `[{"batch":"\ud800","product":"P","quantity":1,"unit":"kg","supplier":"S"}]`,
594			"invalid utf8 batch":        "[{\"batch\":\"B-\xff\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"supplier\":\"S\"}]",
595		}
596		for name, content := range cases {
597			t.Run(name, func(t *testing.T) {
598				_, err := ParseManifest([]byte(content))
599				var re *ManifestRecordError
600				if !errors.As(err, &re) {
601					t.Fatalf("expected ManifestRecordError, got %v", err)
602				}
603				if re.Position != 1 {
604					t.Fatalf("position=%d, want 1", re.Position)
605				}
606				if re.Batch != "" {
607					t.Fatalf("batch=%q, want no batch id (error: %v)", re.Batch, err)
608				}
609				if strings.Contains(err.Error(), "batch \"") {
610					t.Fatalf("error text must not quote a batch id: %v", err)
611				}
612			})
613		}
614	}
615	
616	func TestImportCreatesAndConfirmsRepeats(t *testing.T) {
617		reg := &Registry{Version: FormatVersion, Batches: []Batch{
618			{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"},
619		}}
620		inputs := []Input{
621			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"},
622			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"}, // same-manifest duplicate
623			{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"},    // stored duplicate
624			{Batch: "NEW2", Product: "P-3", Quantity: 1, Unit: "m"},
625		}
626		out, err := Import(reg, inputs)
627		if err != nil {
628			t.Fatal(err)
629		}
630		wantCreated := []bool{true, false, false, true}
631		for i, want := range wantCreated {
632			if out[i].Created != want {
633				t.Errorf("record %d created=%v, want %v", i+1, out[i].Created, want)
634			}
635			if out[i].Batch.Batch != inputs[i].Batch {
636				t.Errorf("record %d batch=%q", i+1, out[i].Batch.Batch)
637			}
638		}
639		// Stored record first, new batches appended in first-occurrence order.
640		wantBatches := []string{"OLD", "NEW1", "NEW2"}
641		if len(reg.Batches) != len(wantBatches) {
642			t.Fatalf("got %d stored batches: %+v", len(reg.Batches), reg.Batches)
643		}
644		for i, want := range wantBatches {
645			if reg.Batches[i].Batch != want {
646				t.Errorf("stored batch %d = %q, want %q", i, reg.Batches[i].Batch, want)
647			}
648		}
649	}
650	
651	func TestImportConflictWithRegistry(t *testing.T) {
652		original := []Batch{{Batch: "B1", Product: "P-1", Quantity: 3, Unit: "kg"}}
653		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), original...)}
654		_, err := Import(reg, []Input{
655			{Batch: "NEW", Product: "P", Quantity: 1, Unit: "kg"},
656			{Batch: "B1", Product: "P-1", Quantity: 4, Unit: "kg"},
657		})
658		var ce *ManifestConflictError
659		if !errors.As(err, &ce) {
660			t.Fatalf("expected ManifestConflictError, got %v", err)
661		}
662		if ce.Position != 2 || ce.Batch != "B1" || ce.Source != "registry" {
663			t.Fatalf("unexpected conflict: %+v", ce)
664		}
665		if len(ce.Fields) != 1 || ce.Fields[0] != "quantity" {
666			t.Fatalf("fields = %v", ce.Fields)
667		}
668		if len(reg.Batches) != len(original) || reg.Batches[0] != original[0] {
669			t.Fatalf("rejected import mutated the registry: %+v", reg.Batches)
670		}
671	}
672	
673	func TestImportConflictWithinManifestLeavesNothing(t *testing.T) {
674		// The registry does not exist yet: two identical B1 records must add it
675		// once on success, but a differing later record must leave the registry
676		// with no new batches at all.
677		reg := &Registry{Version: FormatVersion}
678		_, err := Import(reg, []Input{
679			{Batch: "B1", Product: "P", Quantity: 1, Unit: "kg"},
680			{Batch: "B2", Product: "P", Quantity: 1, Unit: "kg"},
681			{Batch: "B1", Product: "P", Quantity: 2, Unit: "kg"},
682		})
683		var ce *ManifestConflictError
684		if !errors.As(err, &ce) {
685			t.Fatalf("expected ManifestConflictError, got %v", err)
686		}
687		if ce.Position != 3 || ce.Batch != "B1" || ce.Source != "manifest" || ce.PrevPos != 1 {
688			t.Fatalf("unexpected conflict: %+v", ce)
689		}
690		if len(ce.Fields) != 1 || ce.Fields[0] != "quantity" {
691			t.Fatalf("fields = %v", ce.Fields)
692		}
693		if len(reg.Batches) != 0 {
694			t.Fatalf("rejected manifest left new batches: %+v", reg.Batches)
695		}
696	}
697	
698	func TestImportConflictNamesAllFields(t *testing.T) {
699		reg := &Registry{Version: FormatVersion, Batches: []Batch{
700			{Batch: "B1", Product: "P", Quantity: 1, Unit: "kg"},
701		}}
702		_, err := Import(reg, []Input{{Batch: "B1", Product: "Q", Quantity: 2, Unit: "g"}})
703		var ce *ManifestConflictError
704		if !errors.As(err, &ce) {
705			t.Fatalf("expected conflict, got %v", err)
706		}
707		if got := strings.Join(ce.Fields, ","); got != "product,quantity,unit" {
708			t.Fatalf("fields = %q", got)
709		}
710	}
711	
712	func TestImportEmpty(t *testing.T) {
713		if _, err := Import(&Registry{Version: FormatVersion}, nil); err == nil {
714			t.Fatal("empty manifest must be rejected")
715		}
716	}
