891	// A first registration returns "created"; re-submitting the same record —
892	// spelled with padding and leading zeros that normalize away — confirms the
893	// stored record as "duplicate", echoing the registered four fields as the
894	// only JSON object on stdout. The file keeps exactly its earlier records,
895	// the other batch's fields and position included, and neither its bytes nor
896	// its mtime move during the confirmation.
897	func TestBatchRegisterCLIDuplicateConfirm(t *testing.T) {
898		dir := t.TempDir()
899		registry := filepath.Join(dir, "reg.json")
900	
901		stdout, err := registerCLI(t, registry, "B-000", "P-0", "5", "box")
902		if err != nil {
903			t.Fatal(err)
904		}
905		if res := decodeRegisterResult(t, stdout); res.Status != "created" {
906			t.Fatalf("first registration of B-000 = %+v, want created", res)
907		}
908	
909		stdout, err = registerCLI(t, registry, " B-001 ", " P-7 ", "000120", " kg ")
910		if err != nil {
911			t.Fatal(err)
912		}
913		created := decodeRegisterResult(t, stdout)
914		want := registerResult{Batch: "B-001", Product: "P-7", Quantity: 120, Unit: "kg", Status: "created"}
915		if created != want {
916			t.Fatalf("first registration = %+v, want %+v", created, want)
917		}
918	
919		content, pinned := pinRegistry(t, registry)
920	
921		// The same record with the padding and leading zeros already removed is
922		// the identical effective value: a duplicate, not a new record.
923		stdout, err = registerCLI(t, registry, "B-001", "P-7", "120", "kg")
924		if err != nil {
925			t.Fatalf("identical re-registration must succeed: %v", err)
926		}
927		dup := decodeRegisterResult(t, stdout)
928		want.Status = "duplicate"
929		if dup != want {
930			t.Fatalf("duplicate confirmation = %+v, want %+v", dup, want)
931		}
932		assertRegistryUntouched(t, registry, content, pinned)
933	
934		// Still exactly one record per batch, the other batch first and unchanged.
935		batches := readStoredBatches(t, registry)
936		if len(batches) != 2 {
937			t.Fatalf("registry holds %d records, want 2: %v", len(batches), batches)
938		}
939		if batches[0] != (registerResult{Batch: "B-000", Product: "P-0", Quantity: 5, Unit: "box"}) {
940			t.Fatalf("other batch's record changed: %+v", batches[0])
941		}
942		if batches[1] != (registerResult{Batch: "B-001", Product: "P-7", Quantity: 120, Unit: "kg"}) {
943			t.Fatalf("stored record changed: %+v", batches[1])
944		}
945	}
