1	package batchreg
2	
3	import (
4		"errors"
5		"math"
6		"strconv"
7		"strings"
8		"testing"
9	)
10	
11	// This file is the regression net for the single-batch Register entry point
12	// as reached directly through the Go API: the caller hands in already-built
13	// text and an already-decoded int64 (the command line normalizes text and
14	// parses the quantity before constructing the Input), so Register itself must
15	// refuse invalid input ahead of the duplicate/conflict lookup — whatever the
16	// batch id's registration status.
17	//
18	// The error precedence pinned here is Register's own and must not drift toward
19	// the manifest rule (Import reports encoding before empty text): any empty
20	// text field first, then encoding in batch/product/unit order, then quantity.
21	
22	// copyBatches snapshots the stored records so a test can prove a rejected call
23	// left every field, the count and the order exactly as they were.
24	func copyBatches(reg *Registry) []Batch {
25		return append([]Batch(nil), reg.Batches...)
26	}
27	
28	func assertBatchesIdentical(t *testing.T, got, want []Batch) {
29		t.Helper()
30		if len(got) != len(want) {
31			t.Fatalf("record count changed: got %d (%+v), want %d (%+v)", len(got), got, len(want), want)
32		}
33		for i := range want {
34			if got[i] != want[i] {
35				t.Fatalf("record %d changed:\n got %+v\nwant %+v\nfull registry: %+v", i+1, got[i], want[i], got)
36			}
37		}
38	}
39	
40	// assertRejectedBeforeLookup is the shared contract for every invalid input:
41	// the zero Outcome (no carried record, never Created), an error that is neither
42	// a duplicate confirmation nor a conflict, and a registry left byte-for-byte
43	// equivalent in content, count and order.
44	func assertRejectedBeforeLookup(t *testing.T, reg *Registry, before []Batch, out Outcome, err error) {
45		t.Helper()
46		if err == nil {
47			t.Fatalf("invalid input must be rejected, got outcome %+v", out)
48		}
49		if out.Created {
50			t.Fatalf("a rejection must not report a new record, got %+v", out.Batch)
51		}
52		if out.Batch != (Batch{}) {
53			t.Fatalf("a rejection must carry no registered record, got %+v", out.Batch)
54		}
55		var ce *ConflictError
56		if errors.As(err, &ce) {
57			t.Fatalf("invalid input must be reported as invalid, not as an existing-batch conflict: %v", err)
58		}
59		assertBatchesIdentical(t, reg.Batches, before)
60	}
61	
62	// Invalid input is rejected before the create/duplicate/conflict branch whether
63	// the batch id has never been seen or already belongs to a stored record — the
64	// validity check cannot be skipped by reaching a different lookup outcome.
65	func TestRegisterRejectsInvalidInputBeforeLookup(t *testing.T) {
66		badText := string([]byte{'P', 0xff}) // malformed UTF-8
67		valid := func() Input {
68			return Input{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}
69		}
70	
71		cases := []struct {
72			name     string
73			mutate   func(*Input)
74			classify func(t *testing.T, err error)
75		}{
76			{"empty batch", func(in *Input) { in.Batch = "" }, assertEmptyTextError},
77			{"empty product", func(in *Input) { in.Product = "" }, assertEmptyTextError},
78			{"empty unit", func(in *Input) { in.Unit = "" }, assertEmptyTextError},
79			{"malformed utf8 batch", func(in *Input) { in.Batch = "B" + badText }, makeAssertEncodingError("batch")},
80			{"malformed utf8 product", func(in *Input) { in.Product = badText }, makeAssertEncodingError("product")},
81			{"malformed utf8 unit", func(in *Input) { in.Unit = "kg" + badText }, makeAssertEncodingError("unit")},
82			{"quantity zero", func(in *Input) { in.Quantity = 0 }, assertQuantityError},
83			{"quantity negative", func(in *Input) { in.Quantity = -1 }, assertQuantityError},
84			{"quantity minimum int64", func(in *Input) { in.Quantity = math.MinInt64 }, assertQuantityError},
85		}
86	
87		scenarios := []struct {
88			name    string
89			reg     []Batch
90			prepare func(*Input) // align the bad record with the stored id before mutation
91		}{
92			{
93				name:    "id not registered yet",
94				reg:     nil,
95				prepare: func(in *Input) {},
96			},
97			{
98				name: "id already registered",
99				reg:  []Batch{{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}},
100				// The record starts identical to the stored one; the mutation then
101				// makes it invalid, so a lookup-only implementation would otherwise
102				// call it a conflict (or, for an emptied field, compare on garbage).
103				prepare: func(in *Input) {},
104			},
105			{
106				name: "other batches present must be unaffected",
107				reg: []Batch{
108					{Batch: "A0", Product: "PA", Quantity: 1, Unit: "box"},
109					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
110					{Batch: "C9", Product: "PC", Quantity: 7, Unit: "m"},
111				},
112				prepare: func(in *Input) {},
113			},
114		}
115	
116		for _, sc := range scenarios {
117			t.Run(sc.name, func(t *testing.T) {
118				for _, tc := range cases {
119					t.Run(tc.name, func(t *testing.T) {
120						reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), sc.reg...)}
121						before := copyBatches(reg)
122						in := valid()
123						sc.prepare(&in)
124						tc.mutate(&in)
125	
126						out, err := Register(reg, in)
127						assertRejectedBeforeLookup(t, reg, before, out, err)
128						tc.classify(t, err)
129					})
130				}
131			})
132		}
133	}
134	
135	// The exact motivating case: B1 already holds quantity 10; re-submitting B1
136	// with an empty product and quantity 11 must report invalid input — never a
137	// conflict merely because the quantity differs — and must not overwrite the
138	// stored product or quantity.
139	func TestRegisterEmptyProductOnExistingBatchOutranksQuantityConflict(t *testing.T) {
140		existing := []Batch{
141			{Batch: "A0", Product: "PA", Quantity: 4, Unit: "box"},
142			{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
143		}
144		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), existing...)}
145	
146		out, err := Register(reg, Input{Batch: "B1", Product: "", Quantity: 11, Unit: "kg"})
147		assertRejectedBeforeLookup(t, reg, existing, out, err)
148		assertEmptyTextError(t, err)
149	
150		// Explicitly pin the stored B1 record against an overwrite.
151		if got := reg.Batches[1]; got != existing[1] {
152			t.Fatalf("stored B1 was overwritten: got %+v, want %+v", got, existing[1])
153		}
154	}
155	
156	// When one record carries several problems Register keeps its own order: an
157	// empty text field wins over everything (even a malformed field that comes
158	// first in batch/product/unit order); with no empty field, encoding beats
159	// quantity; among several malformed text fields the first in batch, product,
160	// unit order is named. The manifest ordering (encoding before empty) must not
161	// leak in here.
162	func TestRegisterInvalidInputErrorPrecedence(t *testing.T) {
163		bad := string([]byte{0xff})
164		cases := []struct {
165			name string
166			in   Input
167			want func(t *testing.T, err error)
168		}{
169			// Any empty field outranks any encoding and any quantity problem.
170			{"empty product with malformed unit and zero quantity",
171				Input{Batch: "B1", Product: "", Quantity: 0, Unit: "kg" + bad}, assertEmptyTextError},
172			{"empty unit despite malformed batch",
173				Input{Batch: "B" + bad, Product: "P", Quantity: 1, Unit: ""}, assertEmptyTextError},
174			{"empty product despite malformed batch",
175				Input{Batch: "B" + bad, Product: "", Quantity: -9, Unit: "kg"}, assertEmptyTextError},
176			{"all three text fields empty",
177				Input{Batch: "", Product: "", Quantity: 0, Unit: ""}, assertEmptyTextError},
178	
179			// No empty field: encoding is reported before quantity, field order
180			// batch, product, unit deciding which encoding error is named.
181			{"malformed product outranks zero quantity",
182				Input{Batch: "B1", Product: "P" + bad, Quantity: 0, Unit: "kg"}, makeAssertEncodingError("product")},
183			{"malformed batch outranks malformed product",
184				Input{Batch: "B" + bad, Product: "P" + bad, Quantity: 1, Unit: "kg"}, makeAssertEncodingError("batch")},
185			{"malformed batch outranks malformed unit and negative quantity",
186				Input{Batch: "B" + bad, Product: "P", Quantity: -1, Unit: "u" + bad}, makeAssertEncodingError("batch")},
187			{"malformed product outranks malformed unit",
188				Input{Batch: "B1", Product: "P" + bad, Quantity: 1, Unit: "u" + bad}, makeAssertEncodingError("product")},
189			{"all three text fields malformed names batch",
190				Input{Batch: "b" + bad, Product: "p" + bad, Quantity: 1, Unit: "u" + bad}, makeAssertEncodingError("batch")},
191	
192			// Only a quantity problem: text is present and valid.
193			{"zero quantity on otherwise valid record",
194				Input{Batch: "B1", Product: "P", Quantity: 0, Unit: "kg"}, assertQuantityError},
195			{"negative quantity on otherwise valid record",
196				Input{Batch: "B1", Product: "P", Quantity: -42, Unit: "kg"}, assertQuantityError},
197		}
198	
199		for _, tc := range cases {
200			t.Run(tc.name, func(t *testing.T) {
201				// Run each against both an empty registry and one holding B1, so a
202				// future change that validates only on the create branch is caught.
203				for _, existing := range [][]Batch{
204					nil,
205					{{Batch: "B1", Product: "OLD", Quantity: 123, Unit: "old"}},
206				} {
207					reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), existing...)}
208					before := copyBatches(reg)
209					out, err := Register(reg, tc.in)
210					assertRejectedBeforeLookup(t, reg, before, out, err)
211					tc.want(t, err)
212				}
213			})
214		}
215	}
216	
217	// An empty registry stays empty after any rejection; with records present the
218	// whole slice — fields, count and order — is preserved and no id is affected.
219	func TestRegisterRejectionsLeaveRegistryUntouched(t *testing.T) {
220		t.Run("empty registry stays empty", func(t *testing.T) {
221			reg := &Registry{Version: FormatVersion}
222			invalid := []Input{
223				{Batch: "", Product: "P", Quantity: 1, Unit: "kg"},
224				{Batch: "B", Product: "P", Quantity: 0, Unit: "kg"},
225				{Batch: "B", Product: "P" + string([]byte{0xff}), Quantity: 1, Unit: "kg"},
226				{Batch: "B", Product: "P", Quantity: -1, Unit: ""},
227			}
228			for i, in := range invalid {
229				out, err := Register(reg, in)
230				if err == nil {
231					t.Fatalf("case %d must be rejected", i)
232				}
233				if out.Created || len(reg.Batches) != 0 {
234					t.Fatalf("case %d changed the empty registry: out=%+v batches=%+v", i, out, reg.Batches)
235				}
236			}
237		})
238	
239		t.Run("populated registry keeps fields count and order", func(t *testing.T) {
240			original := []Batch{
241				{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
242				{Batch: "B2", Product: "P-8", Quantity: 20, Unit: "box"},
243			}
244			// Each case targets either the existing id B1 or a new id, but is
245			// invalid; none of these may overwrite B1, reorder B2 or append.
246			cases := []struct {
247				name string
248				in   Input
249			}{
250				{"empty product differing quantity", Input{Batch: "B1", Product: "", Quantity: 11, Unit: "kg"}},
251				{"zero quantity", Input{Batch: "B1", Product: "P-7", Quantity: 0, Unit: "kg"}},
252				{"malformed product differing quantity", Input{Batch: "B1", Product: "P" + string([]byte{0xff}), Quantity: 11, Unit: "kg"}},
253				{"empty unit", Input{Batch: "B1", Product: "P-7", Quantity: 11, Unit: ""}},
254				{"negative quantity new id", Input{Batch: "B3", Product: "P", Quantity: -5, Unit: "kg"}},
255			}
256			for _, tc := range cases {
257				t.Run(tc.name, func(t *testing.T) {
258					reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), original...)}
259					out, err := Register(reg, tc.in)
260					assertRejectedBeforeLookup(t, reg, original, out, err)
261				})
262			}
263		})
264	}
265	
266	// Direct callers submit already-built text: it is not trimmed and not case
267	// folded, unlike the command-line path. Only the empty string is "empty";
268	// whitespace-only text is an ordinary non-empty value and registers.
269	func TestRegisterKeepsDirectTextVerbatim(t *testing.T) {
270		reg := &Registry{Version: FormatVersion}
271	
272		in := Input{Batch: " B1 ", Product: "\tP 7\n", Quantity: 1, Unit: " kg "}
273		out, err := Register(reg, in)
274		if err != nil {
275			t.Fatalf("leading/trailing/interior whitespace is ordinary text: %v", err)
276		}
277		if !out.Created || out.Batch != (Batch{Batch: " B1 ", Product: "\tP 7\n", Quantity: 1, Unit: " kg "}) {
278			t.Fatalf("text must be stored verbatim: %+v", out)
279		}
280	
281		// The identical verbatim record confirms a duplicate; trimming it mentally
282		// to "B1"/"P 7"/"kg" must not happen.
283		if out, err := Register(reg, in); err != nil || out.Created {
284			t.Fatalf("verbatim repeat must be a duplicate: out=%+v err=%v", out, err)
285		}
286	
287		// Whitespace-only values are non-empty on the direct path and create a
288		// distinct batch rather than failing the non-empty rule.
289		ws := Input{Batch: " ", Product: "\t", Quantity: 1, Unit: "\n"}
290		if out, err := Register(reg, ws); err != nil || !out.Created {
291			t.Fatalf("whitespace-only text must be accepted as non-empty: out=%+v err=%v", out, err)
292		}
293		if got := reg.Batches[1]; got != (Batch{Batch: " ", Product: "\t", Quantity: 1, Unit: "\n"}) {
294			t.Fatalf("whitespace-only text not kept verbatim: %+v", got)
295		}
296	
297		// Chinese text, emoji and a genuinely entered U+FFFD are all legal text.
298		for _, in := range []Input{
299			{Batch: "批次-1", Product: "产品😀", Quantity: 1, Unit: "千克"},
300			{Batch: "B" + string(rune(0xfffd)), Product: "P", Quantity: 2, Unit: "kg"},
301		} {
302			if out, err := Register(reg, in); err != nil || !out.Created {
303				t.Fatalf("legal Unicode %+v must register: out=%+v err=%v", in, out, err)
304			}
305		}
306		if len(reg.Batches) != 4 {
307			t.Fatalf("unexpected stored records: %+v", reg.Batches)
308		}
309	}
310	
311	// The quantity window stays usable at both inclusive bounds through the direct
312	// API, and an exactly identical stored record still comes back as a duplicate
313	// rather than a create.
314	func TestRegisterQuantityBoundsAndDuplicateStillSucceed(t *testing.T) {
315		reg := &Registry{Version: FormatVersion}
316	
317		lo := Input{Batch: "LO", Product: "P", Quantity: 1, Unit: "kg"}
318		if out, err := Register(reg, lo); err != nil || !out.Created {
319			t.Fatalf("quantity 1 must register: out=%+v err=%v", out, err)
320		}
321		hi := Input{Batch: "HI", Product: "P", Quantity: MaxQuantity, Unit: "kg"}
322		if out, err := Register(reg, hi); err != nil || !out.Created || out.Batch.Quantity != MaxQuantity {
323			t.Fatalf("quantity %d must register: out=%+v err=%v", MaxQuantity, out, err)
324		}
325	
326		// Exactly identical repeats are duplicate confirmations and add nothing.
327		for _, in := range []Input{lo, hi} {
328			before := len(reg.Batches)
329			out, err := Register(reg, in)
330			if err != nil {
331				t.Fatalf("identical repeat must not error: %v", err)
332			}
333			if out.Created || out.Batch.Quantity != in.Quantity {
334				t.Fatalf("identical repeat must be a duplicate: %+v", out)
335			}
336			if len(reg.Batches) != before {
337				t.Fatalf("duplicate confirmation changed the record count: %+v", reg.Batches)
338			}
339		}
340	}
341	
342	// --- error-shape assertions -------------------------------------------------
343	
344	func assertEmptyTextError(t *testing.T, err error) {
345		t.Helper()
346		var ee *EncodingError
